package com.dvopenlabs.freedom.setup;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import org.json.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

public class PhoneInstallerTest {
    @Rule public TemporaryFolder temp=new TemporaryFolder();File apk,folder;Fake device;JSONObject release,choices;PhoneInstaller installer;
    @Before public void setup()throws Exception{folder=temp.newFolder();apk=new File(folder,"signed-test.apk");Files.write(apk.toPath(),new byte[]{1,2,3});release=new JSONObject().put("sha256",SetupPolicy.sha(Files.readAllBytes(apk.toPath()))).put("certificate","a".repeat(64)).put("versionCode",2).put("minSdk",26);device=new Fake(release);installer=new PhoneInstaller(device,release,apk,new File(folder,"journal"));choices=SetupPolicy.choices("clean","top","medium","comfortable",Collections.singletonList("org.example.video"));}
    @Test public void reviewIsReadOnlyAndCommittedPreviewIsTemporary()throws Exception{JSONObject r=installer.review(choices);assertEquals(0,device.installs);assertEquals(0,device.previews);installer.install(r.getString("planHash"));assertEquals(1,device.installs);assertEquals(1,device.previews);assertEquals("org.example.home/.Main",device.home);assertEquals("old-profile",device.profile);assertEquals("awaiting-tv",installer.journal.last().getString("state"));}
    @Test public void wrongDeviceOrPeerCannotCommit()throws Exception{JSONObject r=installer.review(choices);device.peer="changed";try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals(0,device.installs);}
    @Test public void homeChangeAfterReviewIsNotOverwritten()throws Exception{JSONObject r=installer.review(choices);device.home="another.home/.Main";try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals(0,device.installs);assertEquals("another.home/.Main",device.home);}
    @Test public void changedReleaseBytesAreBlockedBeforeInstall()throws Exception{JSONObject r=installer.review(choices);Files.write(apk.toPath(),new byte[]{9});try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals(0,device.installs);}
    @Test public void newerOrDifferentSignerIsNeverUninstalled()throws Exception{device.current=device.meta();device.current.put("versionCode",3);try{installer.review(choices);fail();}catch(IOException expected){}device.current.put("versionCode",1).put("certificate","b".repeat(64));try{installer.review(choices);fail();}catch(IOException expected){}assertEquals(0,device.installs);}
    @Test public void disconnectAfterCommitIsCheckedNotRetried()throws Exception{JSONObject r=installer.review(choices);device.failAfterInstall=true;try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals("needs-attention",installer.journal.last().getString("state"));assertEquals("installed-no-preview",installer.check().getString("state"));assertEquals(1,device.installs);assertEquals(0,device.previews);}
    @Test public void failedTransferWithOriginalApkCanBeFreshlyReviewed()throws Exception{JSONObject r=installer.review(choices);device.failBeforeInstall=true;try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals("checked",installer.check().getString("state"));device.failBeforeInstall=false;assertNotNull(installer.review(choices));assertEquals(0,device.installs);}
    @Test public void nativeReceiptUsesOutcomeAndDoesNotReplayPreview()throws Exception{JSONObject r=installer.review(choices);installer.install(r.getString("planHash"));device.pending=null;device.receipt=new JSONObject().put("requestId",r.getString("id")).put("outcome","kept").toString();assertEquals("kept",installer.check().getString("state"));assertEquals(1,device.previews);}
    @Test public void unknownOrUnavailableAppsAreNotApplied()throws Exception{try{installer.review(SetupPolicy.choices("clean","top","small","compact",Collections.singletonList("org.unknown.app")));fail();}catch(IOException expected){}assertEquals(0,device.installs);}
    @Test public void unconfirmedTvCannotBeReviewed()throws Exception{device.trusted=false;try{installer.review(choices);fail();}catch(IllegalStateException expected){}assertEquals(0,device.installs);}
    @Test public void replayingApprovalFails()throws Exception{JSONObject r=installer.review(choices);installer.install(r.getString("planHash"));try{installer.install(r.getString("planHash"));fail();}catch(IOException expected){}assertEquals(1,device.installs);}
    @Test public void truncatedJournalTailNeverReplaysAnOperation()throws Exception{SetupJournal j=new SetupJournal(temp.newFolder());j.append(new JSONObject().put("state","installing"));try(FileOutputStream out=new FileOutputStream(j.file,true)){out.write("bad partial last entry".getBytes(java.nio.charset.StandardCharsets.UTF_8));}assertEquals("installing",j.last().getString("state"));}
    @Test public void restoreRejectsSettingsChangedAfterItsReview()throws Exception{JSONObject r=installer.review(choices);installer.install(r.getString("planHash"));device.pending=null;JSONObject approved=installer.reviewRestore(r.getString("id"));device.revision="changed-after-review";try{installer.restore(approved.getString("id"),approved.getString("revision"));fail();}catch(IOException expected){}assertEquals(0,device.restores);}
    @Test public void reviewedRestoreUsesSavedBackupOnly()throws Exception{JSONObject r=installer.review(choices);installer.install(r.getString("planHash"));device.pending=null;JSONObject approved=installer.reviewRestore(r.getString("id"));installer.restore(approved.getString("id"),approved.getString("revision"));assertEquals(1,device.restores);assertEquals("restored",installer.journal.last().getString("state"));}
    @Test public void reconnectCanAppendAfterATornTailWithoutLosingVerifiedHistory()throws Exception{SetupJournal j=new SetupJournal(temp.newFolder());j.append(new JSONObject().put("state","installing"));try(FileOutputStream out=new FileOutputStream(j.file,true)){out.write("partial uncommitted record".getBytes(java.nio.charset.StandardCharsets.UTF_8));}assertEquals("installing",j.last().getString("state"));j.append(new JSONObject().put("state","checked"));assertEquals("checked",j.last().getString("state"));assertEquals(2,java.nio.file.Files.readAllLines(j.file.toPath()).size());}
    @Test public void damagedCompleteRecordIsNeverDiscardedAsATornTail()throws Exception{SetupJournal j=new SetupJournal(temp.newFolder());j.append(new JSONObject().put("state","installing"));try(FileOutputStream out=new FileOutputStream(j.file,true)){out.write("corrupt complete record\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));}try{j.append(new JSONObject().put("state","checked"));fail();}catch(IOException expected){}}
    static class Fake implements PhoneInstaller.Device {
        boolean trusted=true,failBeforeInstall,failAfterInstall;int installs,previews,restores;String revision="test-revision";String peer="peer",home="org.example.home/.Main",profile="old-profile",receipt="";JSONObject current,pending;final JSONObject release;
        Fake(JSONObject r){release=r;}
        JSONObject meta()throws Exception{return new JSONObject().put("sha256",release.getString("sha256")).put("certificate",release.getString("certificate")).put("versionCode",release.getInt("versionCode"));}
        public boolean trusted(){return trusted;}public String peer(){return peer;}public String fingerprint(){return "stable-test-device";}public String home(){return home;}public int api(){return 34;}public List<String> apps(){return Collections.singletonList("org.example.video");}
        public JSONObject installed(File save)throws Exception{return current==null?null:new JSONObject(current.toString());}
        public void install(File apk,String hash)throws Exception{if(failBeforeInstall)throw new IOException("Test transfer lost");installs++;current=meta();if(failAfterInstall)throw new IOException("Test connection lost after install");}
        public void preserveHome(String before){assertEquals(before,home);}public void launch(){}
        public JSONObject nativeCall(String method,JSONObject value)throws Exception{if(method.equals("preview")){previews++;pending=new JSONObject().put("requestId",value.getString("requestId"));}if(method.equals("restore")){restores++;profile=value.getJSONObject("backup").getString("profile");}return new JSONObject().put("schema",1).put("api",1).put("package",SetupPolicy.PACKAGE).put("profile",profile).put("revision",revision).put("pending",pending==null?JSONObject.NULL:pending).put("result",receipt).put("backup",new JSONObject().put("profile",profile));}
    }
}
